There is some text beneath ]]..(not game.player:attr("speaks_shertul") and _t[[which you do not understand: #{italic}#'Ik AMAKTHEL cosio SHER'TUL, ik baladath peris furko masa bren doth benna zi, ik blod is "Fen makel ath goru domus ik denz tro ala fron."'#{normal}#]] or _t[[#{italic}#'And AMAKTHEL made the SHER'TUL, and gave unto us the powers to achieve all that we set our will to, and said to us "Go forth to where the light touches and take all for your own."'#{normal}#]])
	end,
}

newLore{
	id = "shertul-fortress-4",
	category = "sher'tul",
	name = _t"fourth mural painting", always_pop = true,
	image = "shertul_fortress_lore4.png",
	lore = function() return _t[[You see a mural showing a huge metropolis made of crystal, with small islands of stone floating in the air behind it. In the foreground is sitting a Sher'Tul, with a hand stretched up to the sky.
There is some text beneath ]]..(not game.player:attr("speaks_shertul") and _t[[[[SOURCE_MATCH_1]]]] or _t[[#{italic}#'We conquered the world, and built for ourselves towering cities of crystal and fortresses that travelled the skies. But some were not content...'#{normal}#]])
	end,
}

newLore{
	id = "shertul-fortress-5",
	category = "sher'tul",
	name = _t"fifth mural painting", always_pop = true,
	image = "shertul_fortress_lore5.png",
	lore = function() return _t[[This mural shows nine Sher'Tul standing side by side, each holding aloft a dark weapon. Your eyes are drawn to a runed staff held by the red-robed figure in the centre. It seems familiar somehow...
